import type { EyeShape } from "../types";

/**
 * Camera-battery results for the classic eye-silhouette finder system, per
 * template. Generated by `scripts/finder-battery.mjs`: every template ×
 * (frame × ball) combination rendered at 512px and decoded with the
 * non-negotiable camera variants (identity / 50% / JPEG).
 *
 * `FINDER_BATTERY[templateId]` holds one 32-bit mask per frame (in
 * FRAME_ORDER): bit i is set when BALL_ORDER[i] decodes on that template
 * under that frame. `tuneDirection` consults the table before a user's
 * eye/pupil pick reaches the renderer, so the silhouette shown is always
 * one the battery proved on THAT template — the picker can never hand the
 * code a finder the camera battery rejected.
 */
export const FRAME_ORDER = [
  "square",
  "rounded",
  "extra-rounded",
  "circle",
  "target",
  "ticks",
  "classy",
  "leaf",
  "diamond",
  "hex",
] as const;
export type FinderFrame = (typeof FRAME_ORDER)[number];

export const BALL_ORDER = [
  "square",
  "rounded",
  "extra-rounded",
  "circle",
  "classy",
  "diamond",
  "leaf",
  "hex",
] as const;
export type FinderBall = (typeof BALL_ORDER)[number];

