/**
 * The ball that passes the most templates for each frame (argmax over
 * FINDER_BATTERY). Note how far this sits from the classic default: angular
 * frames carry angular/round balls (diamond+diamond 78/81, hex+circle 79/81)
 * — diamond+square and hex+square pass on ZERO templates, which is why a
 * user's bare "diamond eye" pick resolves to a diamond ball, not a square one.
 */
export const BEST_BALL: Record<FinderFrame, FinderBall> = {
  square: "square",
  rounded: "rounded",
  "extra-rounded": "extra-rounded",
  circle: "circle",
  target: "circle",
  ticks: "square",
  classy: "rounded",
  leaf: "leaf",
  diamond: "diamond",
  hex: "circle",
};

/** Visually closest frames, in preference order, per frame. */
export const FRAME_FALLBACK: Record<FinderFrame, FinderFrame[]> = {
  square: ["rounded", "ticks", "extra-rounded", "circle"],
  rounded: ["square", "ticks", "extra-rounded"],
  "extra-rounded": ["rounded", "circle", "target", "classy"],
  circle: ["extra-rounded", "target", "rounded"],
  target: ["circle", "extra-rounded", "rounded"],
  ticks: ["rounded", "square", "extra-rounded"],
  classy: ["rounded", "leaf", "extra-rounded", "square"],
  leaf: ["classy", "rounded", "extra-rounded", "square"],
  diamond: ["hex", "square", "rounded"],
  hex: ["diamond", "square", "rounded"],
};

function toFrame(s: EyeShape): FinderFrame {
  return (FRAME_ORDER as readonly string[]).includes(s) ? (s as FinderFrame) : "square";
}
function toBall(s: EyeShape | undefined): FinderBall | undefined {
  if (s === "target") return "circle"; // same silhouette
  if (s === "ticks") return "rounded"; // same silhouette
  if (s !== undefined && (BALL_ORDER as readonly string[]).includes(s)) return s as FinderBall;
  return undefined;
}

/**
 * Resolve a user's (eye, pupil) pick to the closest (frame, ball) the camera
 * battery proved on this template. Preference order: the exact pair → the
 * frame with its best ball (the frame pick is the louder signal, 7×7 vs 3×3)
 * → the user's ball on the closest frame → the closest frame's best ball →
 * any passing frame. Returns `frame: null` when NO silhouette decodes on the
 * template (e.g. tmpl-wechat) — the caller then keeps the template's own
 * finder rather than shipping a battery-rejected one. An unknown template
 * (no battery row) trusts the pick as-is.
 */
export function safeFinder(
  templateId: string | undefined,
  frame: EyeShape,
  ball: EyeShape | undefined,
): { frame: FinderFrame | null; ball: FinderBall | undefined } {
  const f = toFrame(frame);
  const b = toBall(ball);
  const table = templateId ? FINDER_BATTERY[templateId] : undefined;
  if (!table) return { frame: f, ball: b };
  const passes = (fIdx: number, bIdx: number) => ((table[fIdx] ?? 0) & (1 << bIdx)) !== 0;
  const fi = FRAME_ORDER.indexOf(f);
  if (b !== undefined && passes(fi, BALL_ORDER.indexOf(b))) return { frame: f, ball: b };
  const best = BEST_BALL[f]!;
  if (passes(fi, BALL_ORDER.indexOf(best))) return { frame: f, ball: best };
  for (const alt of FRAME_FALLBACK[f] ?? []) {
    const ai = FRAME_ORDER.indexOf(alt);
    if (b !== undefined && passes(ai, BALL_ORDER.indexOf(b))) return { frame: alt, ball: b };
  }
  for (const alt of FRAME_FALLBACK[f] ?? []) {
    const ai = FRAME_ORDER.indexOf(alt);
    if (passes(ai, BALL_ORDER.indexOf(BEST_BALL[alt]!))) return { frame: alt, ball: BEST_BALL[alt] };
  }
  for (const alt of FRAME_FALLBACK[f] ?? []) {
    const ai = FRAME_ORDER.indexOf(alt);
    const mask = table[ai] ?? 0;
    if (mask === 0) continue;
    for (let bi = 0; bi < BALL_ORDER.length; bi++) if (mask & (1 << bi)) return { frame: alt, ball: BALL_ORDER[bi]! };
  }
  return { frame: null, ball: undefined };
}
